/**  A GitHub pull request of a virtual branch, as the search of the user's pull requests reports it */
export type PullRequest = {
	number: number,
	title: string,
	url: string,
	/**  Merged also for a pull request Patronus merged: it closes it with the label `merged` */
	state: PullRequestState,
	isDraft: boolean,
	/**  null when the repository requires no review */
	reviewDecision: ReviewDecision | null,
	/**  The full branch name on the remote, e.g. `user/virtual/feature-auth` */
	headRefName: string,
	/**
	 *  The branch the pull request merges into, e.g. `master`; an old one may go into a virtual branch
	 *  `user/virtual/auth` (a parent's), which a push retargets to the baseline; empty if unknown
	 */
	baseRefName?: string,
	/**  The commit the pull request shows; differs from the local branch tip until the branch is pushed */
	headRefOid: string,
	/**  null when the head commit has no checks */
	checks: ChecksSummary | null,
	/**  Unix seconds */
	updatedAt: number,
	/**  The latest submitted review of each reviewer, then the requested reviewers without one */
	reviewers: Reviewer[],
	/**  The login of the author; null for a deleted account */
	author: string | null,
};

/**  Whether pull requests can be listed for the repository */
export type PullRequestAvailability = 
/**
 *  The GitHub repository of the branches: `branchdeck.githubRepository`, else the one `origin` pushes to, else the
 *  mirror of the committed Space settings (`.space/repository-settings.json`)
 */
{ status: "available"; owner: string; name: string } | 
/**  No GitHub token: not signed in, `gh` not logged in, no `GH_TOKEN`, no git credentials for github.com */
{ status: "signedOut" } | 
/**  GitHub rejected every token found (401); `source` gave the last one */
{ status: "notAuthenticated"; source: TokenSource } | 
/**
 *  The branches are not on GitHub: `origin` is not on github.com, the Space settings name no GitHub mirror, and
 *  `branchdeck.githubRepository` is not set
 */
{ status: "notGitHub" } | 
/**  GitHub refused the request for its rate limit: ask again after `retry_at` (Unix seconds) */
{ status: "rateLimited"; retryAt: number } | 
/**  The organization enforces SAML SSO and no token is authorized for it; `url` authorizes the token */
{ status: "ssoRequired"; url: string | null } | 
/**
 *  No token can see the repository (a fine-grained token of other repositories, the OAuth app access restrictions of
 *  the organization); `source` gave the last one, `message` is GitHub's
 */
{ status: "noAccess"; source: TokenSource; message: string } | 
/**  The request failed, e.g. offline or timed out */
{ status: "error"; message: string };

/**  What a review of the user says */
export type PullRequestReviewEvent = "approve" | 
/**  Needs a body: GitHub refuses a request for changes without one */
"requestChanges";

export type PullRequestState = "open" | "closed" | "merged";

export type PullRequestsResult = {
	availability: PullRequestAvailability,
	/**  By virtual branch name (without the `{prefix}/virtual/` namespace); empty unless available */
	pullRequests: { [key in string]: PullRequest },
	/**
	 *  The pull requests of the stack branches (`{prefix}/stack/<root>`, the whole stack), by the root of the stack; the
	 *  same preference of one per branch. Never in `pull_requests`: a stack branch is no row
	 */
	stackPullRequests?: { [key in string]: PullRequest },
};

export type PushBranchParams = {
	repositoryPath: string,
	branchPrefix: string,
	branchName: string,
	myEmail: string | null,
	baselineBranch: string,
	/**
	 *  The branch a stacked branch is built on (`BranchStack::effective_base`): its commits are not counted as unpushed
	 *  commits of this branch
	 */
	parentBranch?: string | null,
	/**
	 *  The remote head of the status the user saw (`RemoteStatusUpdate::remote_tip`): the push replaces the remote
	 *  branch only if it is still there. `None`: the status showed no remote branch, and the branch must not exist
	 */
	expectedRemote: string | null,
	/**
	 *  Push Up to Here: the commit of the virtual branch to push instead of its tip, so the remote gets the branch up to
	 *  it and the commits after it stay unpushed. It must be one of the branch's own commits (not of its parent or the
	 *  baseline), newer than `expected_remote` on the same line (`check_push_tip`)
	 */
	tip?: string | null,
};

/**  What a stack push did */
export type PushBranchesOutcome = 
/**  Every branch is at its pushed commit on the remote; their remote statuses, in the order of the branches */
{ type: "pushed"; remoteStatuses: RemoteStatusUpdate[] } | 
/**
 *  The remote branch of `branch_name` (the first such, parents first) was not where the user saw it, so nothing was
 *  pushed: the push is atomic. Every branch was fetched, and `remote_statuses` show what the remote has now, in the
 *  order of the branches; a push with the `remote_tip` of `branch_name` replaces it. `whole_stack`: the one that moved
 *  is the stack branch of the whole stack of `branch_name` (`StackPushBranch::whole_stack`), not its virtual branch,
 *  which may be in the same push (Push with Children of the root)
 */
{ type: "remoteMoved"; branchName: string; wholeStack: boolean; remoteStatuses: RemoteStatusUpdate[] };

export type PushBranchesParams = {
	repositoryPath: string,
	branchPrefix: string,
	myEmail: string | null,
	baselineBranch: string,
	/**  Parents first: the order of the refspecs and of the remote statuses of the outcome */
	branches: StackPushBranch[],
};

/**  What a push did */
export type PushOutcome = 
/**  The remote branch is at the pushed commit */
{ type: "pushed"; remoteStatus: RemoteStatusUpdate } | 
/**
 *  The remote branch was not where the user saw it (`expected_remote`): nothing was pushed. The branch was fetched,
 *  and `remote_status` shows what the remote has now; a push with its `remote_tip` replaces that
 */
{ type: "remoteMoved"; remoteStatus: RemoteStatusUpdate };

export type ReadPatronusCommandReplyParams = {
	repositoryPath: string,
	pullRequestNumber: number,
	commentId: string,
	/**  As in `PostPatronusCommandParams` */
	githubRepository?: string | null,
};

/**  A commit of the unapplied branch that the reapply put on top of HEAD */
export type ReappliedCommit = {
	/**  The commit of the unapplied branch (or of its restored chain) */
	commit: string,
	/**  Its copy on HEAD (with a dry run: the one the reapply writes) */
	newId: string,
	subject: string,
};

export type ReapplyBranchParams = {
	repositoryPath: string,
	/**  The name of the unapplied branch, `<name>` of `{prefix}/unapplied/<name>` */
	branchName: string,
	branchPrefix: string,
	/**  Check only: nothing is written but git objects, and no lock is taken */
	dryRun?: boolean,
};

export type ReapplyBranchResult = {
	/**  `{prefix}/unapplied/<name>`, deleted now (with a dry run: would be) */
	unappliedBranchName: string,
	/**  The branch its commits group into again */
	branch: string,
	/**  Oldest first */
	reapplied: ReappliedCommit[],
	/**  The commits HEAD has already, by their patch or their content: left out */
	present: string[],
	/**
	 *  How many messages got the grouping prefix back (`(<name>) `): a virtual branch keeps none, so a commit whose
	 *  subject groups elsewhere gets it
	 */
	prefixRestored: number,
	previousHead: string,
	newHead: string,
	/**  `ReapplyUndoToken` as it prints; `None` for a dry run */
	undoToken: string | null,
};

/**  What a branch does to the declaration of a dangling reference */
export type ReferenceKind = "removed" | "changed" | "duplicate";

/**  A login GitHub didn't ask to review: the author, a user without access to the repository */
export type RefusedReviewer = {
	login: string,
	/**  What GitHub said, e.g. "Review cannot be requested from pull request author." */
	reason: string,
};

/**
 *  Where commits go: `{"branches": {"auth/login": [ids]}, "unassign": [ids], "issue_groups": {"name": [keys]},
 *  "ungroup_issues": [keys], "unstack": [branches]}`
 */
export type RegroupPlan = {
	/**
	 *  Branch path -> commits: a flat name, or `parent/leaf` with stacked branches on, which stacks `leaf` on `parent` in
	 *  the stack parents and gives a commit that needs a prefix the bare `(leaf)`. Ids may be abbreviated
	 */
	branches?: { [key in string]: string[] },
	/**  Commits whose prefix is removed: they fall back to their issue group or issue branch, or become unassigned */
	unassign?: string[],
	/**
	 *  Issue group name (a branch name without `/`) -> issue keys: the commits without a prefix that carry one of the
	 *  keys are grouped into the name, without a rewrite
	 */
	issue_groups?: { [key in string]: string[] },
	/**  Issue keys whose issue group is removed: their commits fall back to the issue branch of the key */
	ungroup_issues?: string[],
	/**
	 *  Branches made roots: their stack parent is removed, and their commits whose prefix declares a parent get the bare
	 *  `(leaf)`. Needs stacked branches on
	 */
	unstack?: string[],
};

/**
 *  What a remote branch is now, as the asker knows it: the page from its rows (a push moves it without a sync), `bd`
 *  from its sync
 */
export type RemoteFact = {
	/**  The tip of the remote branch; null without one */
	remoteTip: string | null,
	/**
	 *  The remote branch has what the branch has by content: nothing to push (a remote rebuilt on an older baseline
	 *  included)
	 */
	upToDate: boolean,
};

/**  The remote facts of the branches and of the stack branches (by root) */
export type RemoteFacts = {
	branches: { [key in string]: RemoteFact },
	stacks: { [key in string]: RemoteFact },
};

/**  Remote branch status information, by content: the baseline and patch-equivalent (rebased) commits don't count */
export type RemoteStatusUpdate = {
	branchName: string,
	remoteExists: boolean,
	/**
	 *  The commit the remote branch points to, the one the status was computed against; `None` when it does not exist.
	 *  A push leases on it, so it replaces the remote branch only as the status showed it
	 */
	remoteTip: string | null,
	/**  Commits of the branch whose content the remote lacks, oldest first; all the commits of a branch not on the remote */
	unpushedCommits: string[],
	/**
	 *  Commits of the remote whose content the branch lacks and that are no older version of a commit it has: a push drops
	 *  them
	 */
	commitsBehind: number,
	/**
	 *  The newest of the commits behind, newest first, at most `remote_status::DROPPED_COMMITS_LIMIT`, all of them when
	 *  only one more (`commits_behind` is the total)
	 */
	droppedCommits: DroppedCommit[],
	/**
	 *  Commits of the remote that are older versions of commits amended here (author, author time and subject match an
	 *  unpushed commit of the branch, the changes differ; a copy with the same changes on moved lines counts nowhere): a
	 *  push replaces them
	 */
	commitsAmended: number,
	/**
	 *  Commits of the remote that are older versions of commits of the branches a stacked branch is built on (they were
	 *  amended or rebuilt since the branch was pushed): a push replaces them
	 */
	commitsRestacked: number,
	/**
	 *  Commits of the remote that are older versions of commits the baseline has above the remote branch (author, author
	 *  time and subject match a baseline commit, as Update Project finds landed commits; the changes may differ, as when a
	 *  Safe Push landed them rebuilt on a newer target): a push replaces them
	 */
	commitsLanded: number,
	/**
	 *  The newest of the landed commits, newest first, at most `remote_status::DROPPED_COMMITS_LIMIT`, all of them when
	 *  only one more (`commits_landed` is the total)
	 */
	landedCommits: LandedRemoteCommit[],
	/**
	 *  Commits of the branch the remote has by content in another version: their message or author changed here (a
	 *  reword), so a push replaces the remote's copies, which a robot would land as they are
	 */
	commitsReworded: number,
	/**
	 *  Commits of the branches a stacked branch is built on whose content its remote branch lacks (a new commit of the
	 *  parent since the branch was pushed): a Safe Push of the remote branch lands an older piece, so a push replaces it.
	 *  Not among `unpushed_commits`, which are the branch's own; 0 for a branch without a remote branch
	 */
	ancestorCommitsAhead: number,
	/**  Of the unpushed commits, the ones authored by the current user */
	myUnpushedCount: number,
	/**  The remote branch is an ancestor of the local one; false for a rebased branch, which a push overwrites */
	fastForward: boolean,
	/**  Last time this branch was pushed to the remote (Unix timestamp, 0 = never pushed) */
	lastPushTime: number,
};

export type RenameBranchParams = {
	repositoryPath: string,
	/**  The branch (a leaf with stacked branches on) */
	branchName: string,
	newName: string,
};

/**  The settings of Settings → Repository */
export type RepositoryConfig = {
	/**  `branchdeck.stacks`, off by default */
	stacks: ConfigSetting<boolean>,
	/**  `branchdeck.symbols`, on by default */
	symbols: ConfigSetting<SymbolMode>,
	/**  `branchdeck.githubRepository` (`owner/name`) */
	githubRepository: ConfigSetting<string | null>,
	/**  `branchdeck.branchPrefix`, normalized as the branches are named */
	branchPrefix: ConfigSetting<string | null>,
	/**  `branchdeck.resolveByWords`, on by default */
	resolveByWords: ConfigSetting<boolean>,
	/**  `branchdeck.agentLease`, on by default */
	agentLease: ConfigSetting<boolean>,
	/**  `branchdeck.agentSubjectBranch`, off by default */
	agentSubjectBranch: ConfigSetting<boolean>,
	/**  The repository of `origin` or of the Space mirror, which applies when `github_repository` is not set */
	detectedGithubRepository: DetectedGitHubRepository | null,
	/**
	 *  With stacked branches on, the flat branches that turning them off would name beside a branch git cannot keep them
	 *  with (`with_stacks_off_clashes`); empty with stacked branches off
	 */
	stacksOffClashes: FlatNameClash[],
};

/**  A write of one key to the local config; `None` unsets it there (the global value or the default applies again) */
export type RepositoryConfigChange = { key: "stacks"; value: boolean | null } | { key: "symbols"; value: SymbolMode | null } | { key: "githubRepository"; value: string | null } | { key: "branchPrefix"; value: string | null } | { key: "resolveByWords"; value: boolean | null } | { key: "agentLease"; value: boolean | null } | { key: "agentSubjectBranch"; value: boolean | null };

/**  The view of the branch table of the last sync */
export type RepositoryView = {
	revision: number,
	/**  Counts the syncs whose table the view is of; 0 before the first */
	tableGeneration: number,
	/**
	 *  Counts the finished computations of the landing needs of the repository: the page waits for the next one
	 *  (`wait_landing_needs`) while a branch's are unknown, then asks the view again
	 */
	landingGeneration: number,
	patronus: PatronusView,
};

export type RequestPullRequestReviewersParams = {
	repositoryPath: string,
	pullRequestNumber: number,
	/**  GitHub logins of users; a team is not asked (`team_reviewers`) */
	reviewers: string[],
};

/**  What GitHub did with a request for reviews of a pull request */
export type RequestedReviewers = {
	/**  The logins GitHub asked to review, as they were given */
	requested: string[],
	/**  The logins it refused, each with its reason */
	refused: RefusedReviewer[],
};

/**  A file of `WordResolutionSummary` */
export type ResolvedFileSummary = {
	path: string,
	conflicts: number,
};

export type RestackBranchParams = {
	repositoryPath: string,
	branchName: string,
	/**  The branch to stack on; `None` makes the branch a root (unstack) */
	parent: string | null,
};

export type RestoreBranchHeadParams = {
	repositoryPath: string,
	/**  HEAD the squash left; the undo is refused if the branch moved since */
	expectedHead: string,
	previousHead: string,
};

export type RetargetPullRequestParams = {
	repositoryPath: string,
	pullRequestNumber: number,
	/**  The branch the pull request merges into from now on, as GitHub names it (`master`, `user/virtual/login`) */
	base: string,
};

/**  A commit of the pull request */
export type ReviewCommit = {
	id: string,
	subject: string,
	/**  The full message, the subject included, without trailing newlines */
	message: string,
	author: string,
	/**  Unix seconds */
	authorTime: number,
	/**  Unix seconds; the time popover of the commit names it when it differs from `author_time` */
	committerTime: number,
};

export type ReviewDecision = "approved" | "changesRequested" | "reviewRequired";

/**  A changed file of a review with the blobs of its sides */
export type ReviewFileSides = {
	path: string,
	oldPath: string | null,
	oldId: string | null,
	newId: string | null,
	/**  The new side is the file of the working tree */
	worktree: boolean,
};

/**  How the fetched branch relates to the commit the pull request shows */
export type ReviewHeadState = 
/**  The source has the commit the pull request shows (or nothing was fetched: it was local) */
"same" | 
/**  The source branch has commits after it: the mirror has not got them yet */
"sourceAhead" | 
/**  The source branch has other commits: it was force-pushed since */
"diverged" | 
/**  The commit the pull request shows could not be fetched: the review shows the source branch */
"missing";

/**  Who told which paths a reviewer group owes */
export type ReviewPathsSource = 
/**  Patronus, from the rules it checked */
"patronus" | 
/**  The `OWNERSHIP` files of the baseline: the paths whose owner has the name of the group */
"ownership" | 
/**
 *  Neither: Patronus sends no paths and no path is owned by the group by name (a delegated review, or other
 *  reviewers named by `review-rules.yaml`)
 */
"unknown";

/**  What the review of a pull request diffs: `base..head`, as GitHub's "Files changed" */
export type ReviewRange = {
	/**  The merge base of the head and the base branch */
	base: string,
	/**  The commit the review shows: the one the pull request shows when it could be fetched */
	head: string,
	headState: ReviewHeadState,
	source: ReviewSource,
	/**  `base..head`, oldest first */
	commits: ReviewCommit[],
};

/**
 *  Whether a Safe Push of the branch, started as `ReviewStart` says, would pass the code-owner review: Patronus decides
 *  (`patronus::review_readiness`), the app and `bd` render it
 */
export type ReviewReadiness = 
/**  The changes need no approval */
{ kind: "notRequired" } | 
/**  Every group the changes need approved the pull request */
{ kind: "approved"; groups: ApprovedReviewGroup[] } | 
/**  A Safe Push would fail for approvals: the groups still short of them */
{ kind: "missing"; groups: MissingReviewGroup[]; 
/**  Approvers of the pull request Patronus doesn't count: no eligible member of a group (a bot, a colleague) */
notCounted: Person[]; reason: MissingApprovalsReason } | 
/**  Patronus doesn't tell whether the approvals of the pull request count */
{ kind: "unknown"; reason: UnknownReadinessReason } | 
/**  Patronus didn't answer */
{ kind: "unavailable"; reason: UnavailableReadinessReason; message: string };

/**  A branch whose review readiness the app asks, at the tip it shows */
export type ReviewReadinessBranch = {
	/**
	 *  The virtual branch, without the `{prefix}/virtual/` namespace; with `source`, only the key the answer comes back
	 *  with (the app's `stack:<root>`)
	 */
	branchName: string,
	/**
	 *  The branch the robot would start from, without `refs/heads/`, when it is not the virtual branch of `branch_name`:
	 *  the stack branch `{prefix}/stack/<root>` of the whole stack, whose commits `tip` names. Patronus is asked about
	 *  it; null for the virtual branch
	 */
	source?: string | null,
	/**  The full commit id the answer is about; the commits are those of it the baseline lacks */
	tip: string,
	start: ReviewStart,
	/**  The reviewers of the pull request of the start, as the app shows them; empty for a start through the API */
	reviewers?: Reviewer[],
	/**  The author of the pull request of the start */
	author?: string | null,
};

/**
 *  A pull request of someone else that waits for the user's review: the user is a requested reviewer by name
 *  (`user-review-requested:@me`), not only through a team
 */
export type ReviewRequest = {
	number: number,
	title: string,
	url: string,
	/**  The description as plain text; empty without one */
	bodyText: string,
	/**  The login of the author; None for a deleted user */
	author: string | null,
	/**
	 *  The login of who asked the user for the review (the actor of the newest review request of the user); None if
	 *  unknown
	 */
	requestedBy: string | null,
	/**  Unix seconds */
	createdAt: number,
	/**  Unix seconds */
	updatedAt: number,
	/**  Unix seconds: when the user was asked for the review the last time, else when the pull request was opened */
	requestedAt: number,
	/**
	 *  Unix seconds: since when it is the user's turn: `requested_at`, or the move of the other side after the user
	 *  answered with a comment (`back_to_you`)
	 */
	waitingSince: number,
	/**  The user answered the request with a comment and the other side moved since; None otherwise */
	backToYou: BackToYou | null,
	additions: number,
	deletions: number,
	changedFiles: number,
	/**  The checks of the head commit; None without checks */
	checksState: ChecksState | null,
	/**  null when the repository requires no review */
	reviewDecision: ReviewDecision | null,
	/**  The user reviewed before and was asked again */
	reRequested: boolean,
	/**  The commit the user's latest submitted review was on; None if the user has not reviewed */
	reviewedCommit: string | null,
	/**  The branch of the pull request, e.g. `alice/virtual/feature-auth` */
	headRefName: string,
	/**  The commit the pull request shows */
	headRefOid: string,
	/**  The branch it merges into */
	baseRefName: string,
	/**  The tip of the base branch as GitHub knows it */
	baseRefOid: string,
	/**  The pull request comes from a fork */
	isCrossRepository: boolean,
	/**  The base is the default branch of the repository */
	baseIsDefault: boolean,
};

export type ReviewRequestsResult = {
	availability: PullRequestAvailability,
	/**
	 *  All pull requests waiting for the user, also those beyond `requests`: GitHub's `issueCount` without the requests
	 *  of the answer that don't wait (reviewed, or answered with a comment)
	 */
	totalCount: number,
	/**  At most 50, as GitHub returns them; empty unless available */
	requests: ReviewRequest[],
};

/**  Where the review of a pull request was fetched from */
export type ReviewSource = 
/**  Both commits were local: nothing was fetched */
"local" | 
/**  `origin` */
"origin" | 
/**  GitHub, a remote or the URL of the repository */
"gitHub";

/**  How the robot of a Safe Push would start, which decides whose approvals count */
export type ReviewStart = 
/**  From the `/patronus` comment of the open pull request into the target: its approvals count */
{ kind: "pullRequest"; number: number } | 
/**  Through the API: no pull request is linked, no approval of one counts */
{ kind: "rest" };

export type Reviewer = {
	/**  The user login, or the team slug */
	login: string,
	/**  The latest submitted review; `Requested` for a requested reviewer without one */
	state: ReviewerState,
	/**  An open review request: never reviewed, or asked again after the review of `state` */
	requested: boolean,
};

/**  What Patronus makes of the review of a group member in the pull request, as the robot started from it would */
export type ReviewerApprovalState = 
/**  The latest review approves; it counts, a stale one too */
"approved" | 
/**  The author, whose own approval the group allows */
"authorSelfApproved" | 
/**  Asked to review, or the latest review comments, requests changes or was dismissed */
"reviewing" | 
/**  Neither asked nor reviewed */
"notAdded" | 
/**  The approval of the member can't count (the author where self-approval isn't allowed, an unavailable member) */
"notEligible";

export type ReviewerState = "approved" | "changesRequested" | "commented" | 
/**  Asked to review, no review submitted yet */
"requested";

/**  The app's reword: the commits of `rewords` (the app sends full ids and whole messages) in the repository */
export type RewordRequest = {
	repositoryPath: string,
	rewords: CommitReword[],
};

export type RewordResult = {
	/**  Request commit id -> new commit id; a commit that was not recreated maps to its own (full) id */
	newCommitIds: { [key in string]: string },
	previousHead: string,
	/**  `previous_head` when no message changed */
	newHead: string,
	/**  The token of `undo_regroup` (`UndoToken`); `None` when nothing changed */
	undoToken?: string | null,
};

/**  The new text of a commit; `{"message": …}` or `{"subject": …}` in the app's request */
export type RewordText = 
/**  The whole message, the `(prefix)` of the subject included */
({ message: string }) & { subject?: never } | 
/**  The subject line, the `(prefix)` included; the body stays */
({ subject: string }) & { message?: never };

export type RobotCommit = {
	/**  The commit of the checked-out branch; null for a commit only the robot had (`removed`, `landed`) */
	localId: string | null,
	/**
	 *  The subject of the commit of the checked-out branch, with its `(prefix)`; for a commit only the robot had, the
	 *  subject of the virtual copy, without it
	 */
	subject: string,
	/**  Unix seconds */
	authorTime: number,
	/**
	 *  The virtual branch of the commit (without the namespace): the branch of the robot, or an ancestor of a stacked
	 *  branch, whose commits the robot built too; null for a commit only the robot had
	 */
	branch: string | null,
	state: RobotCommitState,
};

/**
 *  The commits of a branch against those its robot checked, by the hashes of the checked-out branch: the virtual
 *  branch copies the commits, Patronus rebases them, so no hash `TeamCity` reports is local. A stacked branch has the
 *  commits of its ancestors too: its robot builds the whole stack.
 */
export type RobotCommitMap = {
	/**  Newest first: the commits of the virtual branch, then those the robot had and the branch no longer has */
	commits: RobotCommit[],
	/**
	 *  The robot's source revision is not in the repository (started on another machine, or pruned): every commit is
	 *  `unknown`
	 */
	sourceMissing: boolean,
	/**  The checked-out branch has commits of the branch the virtual branch lacks (not synced since): they are not listed */
	virtualBehindHead: boolean,
};

export type RobotCommitState = 
/**  The robot checked this commit as it is */
"tested" | 
/**  A copy on a newer baseline with the same changes: checked */
"rebased" | 
/**  Changed (amended) since the robot ran */
"changed" | 
/**  Added after the robot ran: not checked */
"added" | 
/**  The robot had it, the branch no longer has it */
"removed" | 
/**  The robot had it, and it is in the baseline now (merged meanwhile, e.g. by the Safe Push of a parent) */
"landed" | 
/**  The robot's commits are unknown (`source_missing`) */
"unknown";

/**  A failed or failing robot as an agent needs it to fix the branch */
export type RobotFailure = {
	robot: PatronusRobot,
	/**  Still running (a required check failed, `robot_is_failing`): more checks may fail */
	running: boolean,
	/**
	 *  The commit `TeamCity` built: the source revision rebased onto the target (`testReferenceRevision`); null before the
	 *  rebase or when Patronus doesn't say
	 */
	testRevision: string | null,
	/**  The commit of the target branch the robot rebased onto (`targetRevision`) */
	targetRevision: string | null,
	kind: RobotFailureKind,
	/**  The failed checks, the last attempt of each; for a running robot also the running checks with a failed build */
	checks: FailedCheck[],
	/**  The problems of severity error, e.g. a conflict of the rebase */
	problems: RobotFailureProblem[],
	/**  The failed builds of the checks with their problems and failed tests: only the full version, null in the fast one */
	builds: FailedBuild[] | null,
	/**  What the limits left out */
	omitted: OmittedFailures,
};

/**  What failed, which decides the first step: a restart for builds that never started, a fix otherwise */
export type RobotFailureKind = 
/**  Checks failed */
"checks" | 
/**
 *  Every failed check failed only to start its builds and ran no failing test: the CI, not the branch; a restart is
 *  the first step
 */
"infrastructure" | 
/**
 *  Patronus detected a massive failure of tests or builds (`MASSIVE_*_FAILURE_DETECTOR`): the branch may break a
 *  core module, or the target is broken
 */
"massive" | 
/**  No check failed, but Patronus reports an error, e.g. the rebase onto the target conflicted */
"patronus" | 
/**  Nothing failed and no error is reported */
"unknown";

export type RobotFailureProblem = {
	title: string,
	subsystem: string | null,
	/**  Markdown, cut to the limit */
	details: string | null,
};

/**  The failure of a robot and the commit map of its branch, for the prompt */
export type RobotFailureReport = {
	failure: RobotFailure,
	/**  null when the branch has no row (archived) or the robot has no source revision */
	commits: RobotCommitMap | null,
	/**  The checked-out branch, whose commits the agent fixes; null when HEAD is detached */
	headBranch: string | null,
};

/**  A branch a merged robot landed, whichever robot the branch's `landedBy` names (`closeLandedPullRequests`) */
export type RobotLandedBranch = {
	branch: string,
	own: boolean,
	after: string[],
};

/**
 *  Which robot belongs to each branch and to each whole stack (by root), as the asker matched them
 *  (`find_branch_robot`, `findBranchRobot`): by robot id
 */
export type RobotMatch = {
	branches: { [key in string]: string },
	stacks: { [key in string]: string },
};

/**  A robot of another branch, or of the whole stack of a root, and what it does to a branch */
export type RobotOf = {
	/**  The branch the robot ran on; the root for the robot of the whole stack */
	branch: string,
	robotId: string,
	/**  The robot of the whole stack of the root `branch` */
	wholeStack: boolean,
};

/**  `bd robot-stats` and the Landing view */
export type RobotStats = {
	window: StatsWindow,
	/**  The user's robots */
	mine: Delivery,
	/**  Everyone else in the repository, as the median person; null while fewer than `MIN_PEOPLE` landed */
	everyone: EveryoneDelivery | null,
	/**  Of the user's merges, those without a failed robot of the same branch in the 3 days before: an estimate */
	first_try: Share | null,
	value: LandingValue,
	time: TimeSpent,
	failures: FailureCauses,
	/**  Workdays only, by the local hour a merged robot started: 24 hours */
	start_hours: StartHour[],
	coverage: Coverage,
};

/**  The progress of a read, and the numbers of the lists before the runs are read */
export type RobotStatsEvent = { type: "progress"; data: {
	lists_read: number,
	lists_total: number,
	runs_read: number,
	runs_total: number,
} } | { type: "partial"; data: RobotStats };

export type RobotStatsResult = {
	availability: PatronusAvailability,
	/**  Patronus failed, the numbers are of what was kept */
	stale: boolean,
	/**  Unix seconds: when the newest list was read; null without one */
	fetched_at: number | null,
	stats: RobotStats | null,
};

/**  A declaration of a text: its lines and its label, `Outer › inner` */
export type Scope = {
	/**  0-based, the end exclusive */
	startLine: number,
	endLine: number,
	label: string,
};

export type SearchGitHubUsersParams = {
	repositoryPath: string,
	query: string,
};

/**  Whether the search tried every candidate */
export type SearchState = "complete" | 
/**  It stopped at the trial or time limit: another search may find more */
"budget" | "canceled";

export type SetRepositoryConfigParams = {
	repositoryPath: string,
	change: RepositoryConfigChange,
	/**  The local config when omitted */
	scope?: WriteScope,
};

export type Share = {
	count: number,
	total: number,
};

/**  A value of each of the three sides of a merge */
export type Sides<T> = {
	left: T,
	base: T,
	right: T,
};

/**
 *  A running robot of a branch built on this one, or of its whole stack, whose commit has commits of it: it lands them
 *  with it
 */
export type SpanView = {
	by: RobotOf,
	/**
	 *  The commits of this branch the robot's commit has, as its content told; null when only the stack as it is now
	 *  tells (its commit is not in the repository)
	 */
	carried: Carried | null,
};

export type Spread = {
	median: number,
	/**  The 90th percentile (nearest rank) */
	p90: number,
};

export type SquashCommitsParams = {
	repositoryPath: string,
	/**  Commits on the current branch (the original commits of virtual branch commits), in any order */
	commitIds: string[],
	/**  The whole message of the squashed commit, the grouping prefix `(branch)` included */
	message: string,
};

export type SquashCommitsResult = {
	/**  The squashed commit, in place of the oldest selected one */
	newCommitId: string,
	/**  HEAD after the squash and before it, for an undo */
	newHead: string,
	previousHead: string,
	squashedCount: number,
};

export type SquashFixupsParams = {
	repositoryPath: string,
	/**  HEAD of the plan the user confirmed; the squash is refused if the branch moved since */
	expectedHead: string,
	scope: AutosquashScope,
};

export type SquashFixupsResult = {
	/**  One entry per target, oldest first */
	squashed: SquashedTarget[],
	/**  Number of fixup commits folded into their targets */
	squashedCount: number,
	/**  Fixups of the scope left as they are: no target in this range */
	orphans: OrphanFixup[],
	/**  HEAD after the squash and before it, for an undo */
	newHead: string,
	previousHead: string,
};

export type SquashedTarget = {
	target: string,
	newId: string,
};

export type StackBlock = {
	parent: string,
	reason: BlockReason,
};

/**
 *  The commit of a stack branch whose copy conflicts with the commits of the stack before it, and the conflicting
 *  paths
 */
export type StackBranchConflict = {
	/**  The original commit, as in `GroupedBranchInfo::commits` */
	commit: string,
	files: string[],
};

/**  How the stack branch of a stack (`{prefix}/stack/<root>`) stands after a sync */
export type StackBranchState = 
/**  The ref is the build of the stack's commits as the sync grouped them: the only state whose ref may be pushed */
"Built" | 
/**  A member failed or is blocked (`StackBranchUpdate::blocked_by`): the stack branch is not rebuilt */
"Blocked" | 
/**  A commit conflicts with the commits of the stack before it (`StackBranchUpdate::conflict`): not rebuilt */
"Conflict" | 
/**
 *  Not rebuilt for another reason (`StackBranchUpdate::error`): the stack no longer forks and the ref stays for its
 *  remote branch, another process moved the ref, or the build failed
 */
"Stale";

/**
 *  The stack branch of a stack after a sync: all commits of a stack that forks, in the order of the checked out
 *  branch's history, on the base of the sync, as one more virtual branch (`{prefix}/stack/<root>`), which a Safe Push
 *  of the whole stack lands in one robot. Sent once per stack branch the sync reports (`BranchesGrouped::stack_branches`)
 */
export type StackBranchUpdate = {
	/**  The root branch of the stack, which names the stack branch */
	root: string,
	/**  The full branch name, `{prefix}/stack/<root>` */
	branchName: string,
	/**
	 *  The branches of the stack, the root first, each after its parent; empty for a stack branch whose stack no longer
	 *  forks
	 */
	members: string[],
	/**  The commits of the stack: every commit of its members */
	commitCount: number,
	state: StackBranchState,
	/**
	 *  The tip of the ref after the sync: the build for `Built`, else the tip the ref kept, which no push may send; `None`
	 *  without a ref
	 */
	tip: string | null,
	/**  `Blocked`: the member that failed or is blocked */
	blockedBy: StackMemberBlock | null,
	/**  `Conflict`: the commit that conflicts and its files */
	conflict: StackBranchConflict | null,
	/**  `Stale`: why the ref was not rebuilt */
	error: string | null,
	/**
	 *  The remote status of `tip` against its remote branch on `origin`, by content as for a virtual branch; `None`
	 *  without a ref or when it could not be computed
	 */
	remote: RemoteStatusUpdate | null,
};

/**  A commit ahead of the baseline, as `StackIndependence` and the refusals of the landing gate name it */
export type StackCommit = {
	id: string,
	/**  The subject without its prefix; an autosquash marker stays */
	subject: string,
	/**  The branch the commit is in */
	branch: string,
};

/**  What fixes a stack problem: `bd` prints it as a command, the app offers it as the action of the branch menu */
export type StackFix = 
/**  Stack the branch on this parent (`bd restack <branch> <parent>`, Stack On ‹parent›) */
{ StackOn: string } | 
/**  Make the branch a root (`bd unstack <branch>`, Unstack) */
"Unstack" | 
/**  Give the branch another name (`bd rename`, Rename…) */
"Rename" | 
/**  Change the prefix of the commits `StackProblemView::commits` names (`bd reword`, Reword… of the commit) */
"Reword";

/**  Whether a stacked branch builds on the baseline without its parent (`stack_independence`) */
export type StackIndependence = 
/**
 *  Built as a root, the branch applies cleanly; with `branchdeck.symbols on` the uses of names its ancestors add are
 *  named, else a compile dependency on the parent is not seen
 */
{ kind: "builds"; 
/**  The declared parent the branch is stacked on */
parent: string; 
/**
 *  The names commits of the branch use that commits of its declared ancestors add (`symbol_dependencies`): applies
 *  alone, but would not compile; empty when none, or the symbols are not on
 */
uses: StackUse[]; 
/**  The symbols were read (`branchdeck.symbols on`): an empty `uses` says that no name of an ancestor is used */
symbols: boolean } | 
/**  Built as a root, a commit of the branch conflicts */
{ kind: "needs"; parent: string; 
/**  The first commit of the branch that conflicts */
childCommit: StackCommit; 
/**  The files it conflicts in */
files: string[]; 
/**
 *  The commits of the ancestors the branch needs, and the commits of the ancestors these need, oldest first, each
 *  with its fixup unit (a move takes a target with its fixups): what a move into the branch moves. By the line
 *  dependencies (`dependencies.rs`), so empty when no commit of an ancestor explains the conflict
 */
parentCommits: StackCommit[]; 
/**
 *  `parent_commits` can move into the branch: no commit left in a branch whose build holds one of them (the
 *  ancestors that own one, and the branches built on those, but not this branch and the branches built on it)
 *  depends on them. Otherwise a move makes that branch need this one
 */
movable: boolean };

export type StackIndependenceParams = {
	repositoryPath: string,
	branchPrefix: string,
	/**  A stacked branch */
	branchName: string,
};

/**
 *  The member of a stack that keeps its stack branch from being built, and why: `Error` for a stack problem or a failed
 *  build, `Conflict` for a merge conflict of its own branch, `Blocked` when its parent can't be built on
 */
export type StackMemberBlock = {
	member: string,
	reason: BlockReason,
};

/**  A branch of the stack, as the app's form of the stack's pull request sends it: what its row shows */
export type StackMemberSubjects = {
	name: string,
	/**  The branch it is built on; null for the root */
	parent: string | null,
	/**  The subjects of its commits without their prefix, oldest first */
	subjects: string[],
};

/**  The Patronus facts of the whole stack of a root; a stack with none is not listed */
export type StackPatronus = {
	/**  The first branch of the stack whose robot runs and pushes: it lands a part of the stack */
	landingMember: RobotOf | null,
	/**  The robot of the whole stack runs on its stack branch and pushes: a push of the stack branch fails it */
	holdRobotId: string | null,
	startBlocked: boolean,
	start: StartRefusal | null,
	dryRun: StartRefusal | null,
};

/**  Why a branch of a stack can't be placed; it never fails the other branches */
export type StackProblem = 
/**  Commits declare different parents, in first-declared order */
({ ConflictingParents: DeclaredParent[] }) & { Cycle?: never; LeafCollision?: never; SelfParent?: never; Syntax?: never } | 
/**  Following the declared parents leads back to the branch: the branches of the cycle, starting with this one */
({ Cycle: string[] }) & { ConflictingParents?: never; LeafCollision?: never; SelfParent?: never; Syntax?: never } | 
/**  `(a/a)`: the commits that declare the branch as its own parent */
({ SelfParent: string[] }) & { ConflictingParents?: never; Cycle?: never; LeafCollision?: never; Syntax?: never } | 
/**  Another branch has the same name ignoring case (`Login` and `login`) */
({ LeafCollision: string }) & { ConflictingParents?: never; Cycle?: never; SelfParent?: never; Syntax?: never } | 
/**  `(a//b)`: the commits whose prefix has an empty level */
({ Syntax: string[] }) & { ConflictingParents?: never; Cycle?: never; LeafCollision?: never; SelfParent?: never };

/**
 *  A stack problem as the row, the menu and `bd` say it: one rule (`history_rewrite::stack::problem_view`), so the app
 *  shows what Rust decides and `bd` prints the same fixes as commands
 */
export type StackProblemView = {
	problem: StackProblem,
	/**  The status of the row: "conflicting parents" */
	label: string,
	/**  Why the branch can't be rebuilt, rewritten or pushed, naming it: "login has conflicting parents" */
	reason: string,
	/**
	 *  The problem with its parents or commits, without commands: "Commits declare different parents: auth (1a2b3c4d),
	 *  core (its stack parent)"
	 */
	message: string,
	/**  The commits to reword (`StackFix::Reword`); empty for the other fixes */
	commits: string[],
	/**  What fixes it, in the order they are offered; never a fix that would add a problem (a parent stacked on the branch) */
	fixes: StackFix[],
};

/**  One branch of a stack push (`PushBranchesParams`) */
export type StackPushBranch = {
	branchName: string,
	/**
	 *  The branch it is built on (`BranchStack::effective_base`): its commits are not counted as unpushed commits of
	 *  this branch
	 */
	parentBranch?: string | null,
	/**
	 *  The remote head of the status the user saw (`RemoteStatusUpdate::remote_tip`): the push replaces the remote
	 *  branch only if it is still there. `None`: the status showed no remote branch, and the branch must not exist
	 */
	expectedRemote: string | null,
	/**  Push Up to Here: the commit to push instead of the tip (`PushBranchParams::tip`) */
	tip?: string | null,
	/**
	 *  The stack branch of the whole stack whose root `branch_name` is (`{prefix}/stack/<root>`), not its virtual branch:
	 *  the caller pushes it only while the sync built it (`StackBranchState::Built`); no parent, no tip
	 */
	wholeStack?: boolean,
	/**
	 *  The unapplied branch `{prefix}/unapplied/<branch_name>`, pushed under its own name so the remote keeps a copy: no
	 *  parent, no tip; a pull request of its virtual branch stays as it was
	 */
	unapplied?: boolean,
};

/**  A use of a name that a commit of an ancestor adds, by a commit of the branch */
export type StackUse = {
	/**  The commit of the branch */
	commit: StackCommit,
	name: string,
	/**  The commit of the ancestor that adds it */
	declaredBy: StackCommit,
};

export type StartHour = {
	/**  Local, 0–23 */
	hour: number,
	/**  Everyone else's merged robots; null while fewer than `MIN_HOUR_PEOPLE` people started one at that hour */
	everyone: HourTime | null,
	/**  The user's; null below `MIN_HOUR_ROBOTS` */
	mine: HourTime | null,
	/**  0 (the fastest hour) to 4 (the slowest) of everyone's medians; null without one */
	level: number | null,
};

export type StartPatronusRobotParams = {
	repositoryPath: string,
	branchPrefix: string,
	baselineBranch: string,
	/**
	 *  The virtual branch, without the `{prefix}/virtual/` namespace; it must be pushed. With `stack`, the root of the
	 *  stack
	 */
	branchName: string,
	/**
	 *  The whole stack of the root `branch_name`: the robot starts from its stack branch `{prefix}/stack/<root>`, which
	 *  must be pushed, and lands every branch of the stack
	 */
	stack?: boolean,
	mode: PatronusPushMode,
	profileId: string | null,
	/**  The merge request whose approvals the review check of the robot counts; null without one */
	mergeRequest: PatronusMergeRequest | null,
	/**  What the user started anyway (Start Anyway); without it the refusals of `sync_core::landing_gate` fail the start */
	allow?: LandingAllowances,
};

/**
 *  Why a start is not possible, for the robot part of the decision; the caller says the rest first (a blocked branch,
 *  one a merged robot landed)
 */
export type StartRefusal = 
/**  A robot runs on the commit the branch is at, or on its remote branch that has the same commits */
{ kind: "lastCommit"; robotId: string } | 
/**  A robot of a branch built on it, or of the whole stack, lands it with more */
{ kind: "descendant"; span: SpanView } | 
/**
 *  A robot lands a part of what the start would land: an ancestor, a side branch built on one; for the whole stack a
 *  branch of it
 */
{ kind: "ancestor"; landing: RobotOf };

export type StatsWindow = {
	/**  Unix seconds */
	start: number,
	end: number,
	/**  The runs (checks, failure causes, commits) count since then */
	runs_start: number,
	/**  The IANA zone of the hours and weeks, e.g. `Europe/Berlin` */
	time_zone: string,
	/**  The branch the robots push into, e.g. `master` */
	target: string,
};

/**  An open of a sub-window, as its page gets it (`window.__SUB_WINDOW_OPEN__`) */
export type SubWindowOpen = {
	/**  Counts the opens of all windows: the page names the open whose content it settled (`sub_window_ready`) */
	id: number,
	/**  When the opener asked (`Date.now()`), for the timing line of the page */
	openedAt: number | null,
};

/**
 *  The data of an open of a sub-window, as `open_sub_window` got it: `__INIT_DATA__`, `__TAURI_STORE__` and
 *  `__SUB_WINDOW_OPEN__` of its page
 */
export type SubWindowUpdate = {
	data: string,
	storeCache: string,
	open: SubWindowOpen,
};

export type SubmitPullRequestReviewParams = {
	repositoryPath: string,
	/**  `owner/name` when the review requests already resolved it: skips resolving the repository again */
	githubRepository: string | null,
	pullRequestNumber: number,
	event: PullRequestReviewEvent,
	/**  The commit the user reviewed: the review is on it, also when the pull request got commits since */
	commitId: string,
	body: string | null,
};

export type SuggestBranchNamesParams = {
	repositoryPath: string,
	/**  The commits of the new branch; the message is not sent, the backend reads it from git with the changed files */
	commits: CommitInfo[],
};

/**  How far the dependencies by symbols reach (`branchdeck.symbols`) */
export type SymbolMode = 
/**  No summaries are read */
"off" | 
/**
 *  `bd commits` reports the dependencies by symbols, and the dangling-reference check subtracts by the trees; nothing
 *  decides by them
 */
"report" | 
/**  They also order and stack branches, and the conflict fix and the checks use them */
"on";

export type SyncBranchesParams = {
	repositoryPath: string,
	branchPrefix: string,
};

/**  Progress events for sync operations */
export type SyncEvent = 
/**  Sent at the beginning with issue navigation configuration if found */
{ type: "issueNavigationConfig"; data: {
	config: IssueNavigationConfig | null,
} } | 
/**  Sent immediately after grouping commits */
{ type: "branchesGrouped"; data: {
	branches: GroupedBranchInfo[],
	/**  Repository's baseline branch (e.g., "origin/master", "master") */
	baselineBranch: string,
	/**  Stacked branches are on (`branchdeck.stacks`): prefixes are read as `(parent/leaf)` */
	stacks?: boolean,
	/**  Issue key -> branch name: the issue groups (`refs/branch-deck/issue-groups`) the commits were grouped with */
	issueGroups?: { [key in string]: string },
	/**
	 *  Child -> parent: the stack parents (`refs/branch-deck/stack-parents`) the branches were placed with; empty with
	 *  stacked branches off
	 */
	stackParents?: { [key in string]: string },
	/**
	 *  Branch -> note: the parked branches (`refs/branch-deck/parked`), kept local and never pushed; also the lines of
	 *  branches that group no commit on this HEAD
	 */
	parked?: { [key in string]: string },
	/**
	 *  The roots of the stack branches this sync reports, each with one `StackBranchUpdate` later: the stacks that fork
	 *  and the stack branches kept for their remote branch; any other stack branch is gone
	 */
	stackBranches?: string[],
} } | 
/**  Sent for commits that don't match any prefix pattern */
{ type: "unassignedCommits"; data: {
	commits: Commit[],
} } | 
/**  Sent when a commit is successfully cherry-picked */
{ type: "commitSynced"; data: {
	branchName: string,
	commitHash: string,
	newHash: string,
	status: CommitSyncStatus,
	/**  The conflict of git that the copy resolved by words (`branchdeck.resolveByWords`); null for a copy without one */
	resolved?: WordResolutionSummary | null,
} } | 
/**  Sent when a commit fails to cherry-pick */
{ type: "commitError"; data: {
	branchName: string,
	commitHash: string,
	error: BranchError,
} } | 
/**  Sent to mark commits as blocked due to earlier error */
{ type: "commitsBlocked"; data: {
	branchName: string,
	blockedCommitHashes: string[],
} } | 
/**  Sent when a branch status changes (including during processing and completion) */
{ type: "branchStatusUpdate"; data: {
	branchName: string,
	status: BranchSyncStatus,
	error: BranchError | null,
} } | 
/**  Unified per-branch detection event for any status (Integrated, Orphaned, `NotIntegrated`, Partial) */
{ type: "branchIntegrationDetected"; data: {
	info: BranchIntegrationInfo,
} } | 
/**  Sent immediately when archived branches are found (before expensive detection) */
{ type: "archivedBranchesFound"; data: {
	branchNames: string[],
	/**  The branches this sync archived, a subset of `branch_names` */
	newlyArchived: string[],
} } | 
/**
 *  The unapplied branches (`{prefix}/unapplied/<name>`), newest first, with the remote status of those on the remote;
 *  sent once per sync, also empty, so the list clears
 */
{ type: "unappliedBranchesFound"; data: {
	branches: UnappliedBranchInfo[],
} } | 
/**  Sent when remote branch status is checked */
{ type: "remoteStatusUpdate"; data: RemoteStatusUpdate } | 
/**
 *  Sent for each stack branch `BranchesGrouped` announced, once the branches of its stack are built: its state, its
 *  tip and its remote status
 */
{ type: "stackBranchUpdate"; data: StackBranchUpdate } | 
/**
 *  Sent once after `BranchesGrouped`: whether the checked out branch can be updated onto the last fetched baseline
 *  (checked without the network). Both fields `None` for a local baseline, which has nothing to update from.
 */
{ type: "baselineStatus"; data: {
	baselineBranch: string,
	update: UpdateCheck | null,
	/**  Why the check failed, e.g. a rebase in progress; the sync itself does not fail */
	checkError: string | null,
	/**  Local commits that the fetched baseline already has: the update drops them */
	landing: LandedBranch[],
	/**  Commits that landed with an update (by Branch Deck or elsewhere) and that the user has not dismissed yet */
	landed: LandedBranch[],
} };

export type SyncInputsParams = {
	repositoryPath: string,
	branchPrefix: string,
};

/**  What the check found */
export type TargetCheck = {
	/**  The baseline the commits were replayed onto, e.g. `origin/master` */
	baseline: string,
	/**  Why the fetch of the target failed; the check then used the last fetched tip. `None` after a fetch */
	fetchError: string | null,
	outcome: TargetOutcome,
};

export type TargetCommit = {
	id: string,
	author: string,
	/**  Unix seconds */
	authorTime: number,
	subject: string,
};

/**  The first commit whose replay onto the target conflicts */
export type TargetConflict = {
	/**  The tip of the target the commits were replayed onto */
	targetTip: string,
	/**  The commit of the branch the robot starts from: a copy of the virtual branch, its subject without the prefix */
	commit: TargetCommit,
	/**  The conflicting files, at most 50 (all of them when only one more) */
	files: string[],
	/**  How many files conflict */
	fileCount: number,
	/**  The commits of the target after the base of the branch that change `files`, the newest 10, oldest first */
	targetCommits: TargetCommit[],
};

export type TargetConflictParams = {
	repositoryPath: string,
	branchPrefix: string,
	/**  As the sync detected it, e.g. `origin/master`: the robot pushes into the branch it tracks */
	baselineBranch: string,
	/**
	 *  The virtual branch the robot starts from, without the `{prefix}/virtual/` namespace; with `stack`, the root of the
	 *  stack
	 */
	branchName: string,
	/**  The whole stack of the root `branch_name`: the robot starts from its stack branch `{prefix}/stack/<root>` */
	stack?: boolean,
};

export type TargetOutcome = 
/**  Every commit applies onto the target tip */
({ kind: "clean" }) & { error?: never } | 
/**  A commit conflicts: Patronus fails the robot before any check */
{
	kind: "conflict",
} & TargetConflict | 
/**  The check did not run to its end: nothing is known */
{ kind: "notRun"; error: string };

/**  The diff of two texts */
export type TextDiff = {
	oldLineCount: number,
	newLineCount: number,
	/**
	 *  The changed lines of the new text under the policy: an `Ignored` block, and the empty line after a final line
	 *  end, do not count
	 */
	additions: number,
	/**  The same for the old text */
	deletions: number,
	/**  The line ends of the two files when they differ; `None` when they are the same, or a file has no line end */
	lineEnds: LineEnds | null,
	/**
	 *  Whether each text ends with a line end, when only one does ("Newline at end of file added"); `None` when they agree,
	 *  or a text is empty (an added or a deleted file)
	 */
	finalNewline: FinalNewline | null,
	/**
	 *  Whether the last line of each text is the empty line that does not count: the line after a final line end, or
	 *  the one line of an empty text. A view hides it when no block touches it, so a file shows no empty last row
	 */
	emptyLastLine: EmptyLastLine,
	/**  The inner ranges were not compared (a side over a limit, or out of time): the blocks are still exact */
	lineLevelOnly: boolean,
	/**  In order and without overlap; the lines between two blocks are equal under the policy */
	blocks: DiffBlock[],
	/**  The declarations of the old text, for the labels of the hunks; empty when not known */
	oldScopes: Scope[],
	newScopes: Scope[],
};

/**  The merge of three texts */
export type TextMerge = {
	leftLineCount: number,
	baseLineCount: number,
	rightLineCount: number,
	/**
	 *  The line ends of the sides (`None` for a side without one) when they differ; `None` when the sides with a line
	 *  end agree
	 */
	lineEnds: Sides<LineEndKind | null> | null,
	/**  Whether each text ends with a line end, when they disagree; `None` when they agree or a text is empty */
	finalNewline: Sides<boolean> | null,
	/**  Whether the last line of each text is the empty line that does not count (`TextDiff::empty_last_line`) */
	emptyLastLine: Sides<boolean>,
	/**
	 *  The inner ranges and the resolve by words were not computed (a side over a limit, or out of time): the blocks are
	 *  still exact, and no conflict resolves by words
	 */
	lineLevelOnly: boolean,
	/**  In order and without overlap; the lines between two blocks are equal on the three sides under the policy */
	blocks: MergeBlock[],
	/**  The blocks that both sides changed differently */
	conflicts: number,
	/**
	 *  The conflicts that no resolution resolves; `conflicts > 0` with `unresolved == 0` is a conflict of git that its
	 *  words resolve
	 */
	unresolved: number,
	leftScopes: Scope[],
	baseScopes: Scope[],
	rightScopes: Scope[],
};

/**  Where the user's robot time went, seconds */
export type TimeSpent = {
	/**  In robots that merged */
	merged: number,
	/**  In robots that failed */
	failed: number,
	canceled: number,
	/**  From a failed or canceled robot to the next robot of the same branch, within 3 days */
	between: number,
};

/**  Where the GitHub token came from, in the order they are tried (`github::token`) */
export type TokenSource = 
/**  `GH_TOKEN`, else `GITHUB_TOKEN` */
"environment" | 
/**  `gh auth token` */
"gh" | 
/**  The app's own sign-in (OAuth device flow) */
"branchDeck" | 
/**  The credential git stores for github.com (`git credential fill`) */
"gitCredential";

/**  How far a fetch or a push is, for the button that runs it */
export type TransferProgress = {
	/**  The whole transfer, 0 to 100, never decreasing */
	percent: number,
	/**  Received (fetch) or sent (push) so far, as git prints it, e.g. "5.79 MiB" */
	transferred: string | null,
	/**  The transfer rate, as git prints it, e.g. "32.57 MiB/s" */
	speed: string | null,
	/**  The last progress line of git, without the `remote: ` prefix, e.g. "Receiving objects:  45% (136/302)" */
	line: string,
};

/**  A branch an unapply kept: its commits are not in HEAD, it lands nothing until it is reapplied */
export type UnappliedBranchInfo = {
	/**  The full name, `{prefix}/unapplied/<name>` */
	name: string,
	/**  `<name>`: the branch it was, a `-N` suffix when that name was taken */
	branch: string,
	tip: string,
	/**  The subject of its tip */
	subject: string,
	/**  A worktree has it checked out */
	checkedOut: boolean,
	/**  Its remote status, when its remote branch exists (a plain push of it); `None` when it is not on the remote */
	remote: RemoteStatusUpdate | null,
};

export type UnapplyBranchParams = {
	repositoryPath: string,
	/**  The branch as the grouping names it (`auth`), not its full virtual branch name */
	branchName: string,
	branchPrefix: string,
	/**
	 *  The original commits the request was made for: when the branch groups others now, the unapply is refused. `None`
	 *  takes the commits as they group now
	 */
	originalCommitIds?: string[] | null,
};

export type UnapplyBranchResult = {
	/**  The full name of the unapplied branch: `{prefix}/unapplied/<name>`, with a `-N` suffix when the name is taken */
	unappliedBranchName: string,
	/**  The original commits that left HEAD, oldest first */
	commitsRemoved: string[],
	/**  HEAD before the unapply */
	previousHead: string,
	/**  HEAD after it */
	newHead: string,
	/**  The undo: `UnapplyUndoToken` as it prints */
	undoToken: string,
};

/**  Why Patronus didn't answer */
export type UnavailableReadinessReason = 
/**  No Space token, an expired one, or Patronus rejected it */
"notLoggedIn" | 
/**  Patronus failed or could not be reached, or is backed off after a failure */
"error";

export type UncommittedChangesResult = {
	hasChanges: boolean,
	files: UncommittedFileChange[],
};

export type UncommittedFileChange = {
	filePath: string,
	status: string,
	staged: boolean,
	unstaged: boolean,
};

export type UndoReapplyParams = {
	repositoryPath: string,
	/**  The `undoToken` of the reapply */
	undoToken: string,
};

export type UndoRegroupParams = {
	repositoryPath: string,
	/**  What the operation reported in `MoveCommitsResult.undo_token` */
	token: string,
};

export type UndoUnapplyParams = {
	repositoryPath: string,
	/**  The `undo_token` of the unapply */
	undoToken: string,
};

/**  What the undo of a reapply did */
export type UndoneReapply = {
	/**  It was undone before: nothing changed now */
	alreadyUndone: boolean,
};

/**  What the undo of an unapply did */
export type UndoneUnapply = {
	/**  It was undone before: nothing changed now */
	alreadyUndone: boolean,
};

/**  Why Patronus can't tell */
export type UnknownReadinessReason = 
/**
 *  The pull request has approvals, and Patronus answers without saying whose count (an older server, or the
 *  evaluation of pull requests is off)
 */
"approvalsNotEvaluated" | 
/**  The branch has too many commits to check, as in the IDE; the robot checks them anyway */
"skipped";

export type UnparkBranchesParams = {
	repositoryPath: string,
	/**  Dropped in one store commit: a branch that is not parked unparks none */
	branchNames: string[],
};

/**  The result of checking the branch against its upstream */
export type UpdateCheck = {
	/**  The checked out branch, short name */
	branch: string,
	/**  The upstream as the user knows it, e.g. `origin/master` */
	upstream: string,
	head: string,
	upstreamHead: string,
	/**  The merge base of HEAD and the upstream */
	base: string,
	state: UpdateState,
	/**  When the upstream was last fetched (Unix seconds), if known */
	fetchedAt: number | null,
	/**
	 *  The local commits whose conflict of git the replay resolved by words (`branchdeck.resolveByWords`), oldest first;
	 *  empty when the replay applies as it is or conflicts
	 */
	resolvedByWords?: UpdateResolvedCommit[],
};

/**  A commit of a conflicting update: a local one that would be replayed, or an upstream one */
export type UpdateCommit = {
	id: string,
	subject: string,
	author: string,
	/**  Author time, Unix seconds */
	time: number,
	/**  Who wrote the commit object: the author, or whoever rebased or landed it (a Safe Push robot) */
	committer: string,
	/**  Committer time, Unix seconds: for an upstream commit, about when it reached the upstream */
	committerTime: number,
	/**  The likely conflicting files that the commit changes; empty for most commits */
	files: string[],
};

/**  The version the app runs and the one it can install */
export type UpdateInfo = {
	current_version: string,
	/**  Empty when no update is available */
	available_version: string,
	is_update_available: boolean,
	status: UpdateStatus,
};

/**  How the branch reaches the upstream */
export type UpdateKind = 
/**  No local commits: the branch moves to the upstream */
"fastForward" | 
/**  The local commits are replayed onto the upstream */
"rebase";

/**  The step an update is at */
export type UpdatePhase = "fetching" | 
/**  Another operation holds the repository lock (`bd`, a regroup); sent only when the update has to wait for it */
"waiting" | "checking" | "updating";

/**  What an update reports while it runs */
export type UpdateProgress = {
	phase: UpdatePhase,
	/**  How far the fetch is; `None` until git reports a stage, and in the other phases */
	fetch: TransferProgress | null,
};

export type UpdateProjectParams = {
	repositoryPath: string,
};

export type UpdateProjectResult = {
	/**  The check against the fetched upstream; on a conflict or a block nothing was changed */
	check: UpdateCheck,
	/**  What the update changed; `None` when up to date, conflicting or blocked */
	applied: AppliedUpdate | null,
	/**  The local commits this update dropped because the upstream has them, by branch */
	landed: LandedBranch[],
};

/**  A local commit whose conflict of git an update resolved by words */
export type UpdateResolvedCommit = {
	/**  The local commit */
	commit: string,
	subject: string,
	/**  The commit the update writes for it; a preview check writes it with a fixed committer date */
	newId: string,
	/**  The conflicts of git that the words resolved: the `<<<<<<<` lines git would have left */
	conflicts: number,
	files: ResolvedFileSummary[],
};

/**  Whether the branch can be updated, relative to the last fetch of the upstream */
export type UpdateState = 
/**  The upstream has nothing the branch lacks */
{ status: "upToDate" } | 
/**  The update applies without conflicts and without touching local changes */
{ status: "clean"; kind: UpdateKind } | 
/**  Replaying the local commits onto the upstream conflicts; nothing was changed */
{ status: "conflict"; 
/**  The files that likely conflict, at most the first `MAX_ATTRIBUTED_FILES`: the ones with their commits */
files: string[]; 
/**  All files that likely conflict: a monorepo update can conflict in thousands */
fileCount: number; 
/**  The local commits, oldest first */
commits: UpdateCommit[]; 
/**
 *  The upstream commits that changed the likely conflicting files, oldest first, at most the newest
 *  `MAX_UPSTREAM_COMMITS`
 */
upstreamCommits: UpdateCommit[] } | 
/**  Uncommitted or staged changes, or untracked files, sit on paths the update would write; nothing was changed */
{ status: "blocked"; 
/**  The paths, at most the first `MAX_BLOCKED_PATHS` */
paths: string[]; 
/**  All paths: untracked files that the upstream adds can be thousands */
pathCount: number };

/**  Where the update is: an available update is downloaded by the check, then installed on request */
export type UpdateStatus = "Idle" | "Checking" | "Downloading" | "Downloaded" | "Installing" | { Error: string };

/**  A commit of the baseline that carries the user's work */
export type UpstreamCommit = {
	id: string,
	author: string,
	committer: string,
	/**  Commit time, Unix seconds */
	time: number,
};

/**  A usage: its place (`kind` is how it uses the name: `declaration`, `import`, `call`, `write`, `read`) and its line */
export type UsageTarget = {
	target: DeclarationTarget,
	/**  The text of its line, without the indent */
	text: string,
	/**  Where the name starts in `text`, in UTF-16 */
	textColumn: number,
};

export type ValidateRepositoryPathParams = {
	path: string,
};

export type WaitForGitHubBranchParams = {
	repositoryPath: string,
	/**  The full branch name on the remote, e.g. `user/virtual/feature-auth` */
	branch: string,
};

/**  What the page waits for while the landing needs of a branch are unknown (`wait_landing_needs`) */
export type WaitLandingNeedsParams = {
	repositoryPath: string,
	branchPrefix: string,
	/**  `landingGeneration` of the view the page has: the wait ends once a computation finished after it, or none runs */
	after: number,
};

export type WeekCount = {
	/**  Unix seconds of the local Monday 00:00 */
	start: number,
	merged: number,
	/**  Finished robots */
	robots: number,
};

/**  The whitespace option of a diff view (`IgnorePolicy`) */
export type WhitespacePolicy = 
/**  Every char counts */
"default" | 
/**  The whitespace at the start and the end of a line does not count */
"trim" | 
/**  No whitespace counts */
"ignore" | 
/**
 *  No whitespace counts, and a block that changed only in whitespace or empty lines at its start or end is cut off
 *  (`IGNORE_WHITESPACES_CHUNKS`)
 */
"ignoreBlankLines";

/**
 *  A copy whose cherry-pick conflicted in git and resolved by words (`word_resolve`): what its mapping note records and
 *  the commit row says ("Resolved 3 conflicts by words")
 */
export type WordResolutionSummary = {
	/**  The parent of the original commit: the base of the merge that the conflict view opens again */
	parent: string,
	/**  The commit the copy is built on: ours of that merge */
	target: string,
	/**  The conflicts of git that the words resolved: the `<<<<<<<` lines git would have left */
	conflicts: number,
	/**  The resolved files */
	fileCount: number,
	/**
	 *  The resolved files with their conflicts, in git's order; empty for a copy reused by its mapping note, which records
	 *  the counts only. The conflict view merges the commit again for them (`get_file_merges`)
	 */
	files: ResolvedFileSummary[],
};

/**  The config file a write of Settings goes to */
export type WriteScope = 
/**  `.git/config` of the repository */
"local" | 
/**  The global config of the user (`git config --global`): every repository without a local value takes it */
"global";

/**  Why the token is not used any more */
export type YouTrackAuthProblem = 
/**  YouTrack answered 401 to the token */
"rejected" | 
/**  Hub refused the refresh token: its time is over, or it was revoked */
"expired";

/**  The YouTrack sign-in as Settings and the issue popover show it */
export type YouTrackAuthStatus = {
	/**  The YouTrack the token is for, e.g. `https://youtrack.example.com`; None without a token */
	url: string | null,
	signedInAs: YouTrackUser | null,
	source: YouTrackTokenSource | null,
	problem: YouTrackAuthProblem | null,
	/**  Unix seconds of the sign-in or the pasted token; None for `YOUTRACK_TOKEN` */
	signedInAt: number | null,
	/**
	 *  Where the user sees and revokes the token: Account Security of the YouTrack profile, or the Hub profile when the
	 *  Hub is not built into the YouTrack (the refresh token of a browser sign-in is listed there)
	 */
	manageUrl: string | null,
};

/**  A single-value field of an issue, by the name YouTrack gives it: "Priority: Major", "Assignee: Jane Doe" */
export type YouTrackField = {
	name: string,
	value: string,
};

export type YouTrackIssue = {
	/**  `IJPL-1` */
	key: string,
	summary: string,
	/**  The issue page: `<YouTrack>/issue/IJPL-1` */
	url: string,
	/**  Unix seconds; None while it is open */
	resolved: number | null,
	state: YouTrackState | null,
	/**  The other single-value fields with a value, in YouTrack's order (enum, user, version, owned) */
	fields: YouTrackField[],
};

/**  The answer to an issue lookup: the issue, or why there is none */
export type YouTrackIssueAnswer = { status: "found"; issue: YouTrackIssue } | 
/**  No token, or the key is not of the YouTrack the token is for */
{ status: "notSignedIn" } | 
/**  The token was rejected, or the sign-in expired */
{ status: "signInProblem"; problem: YouTrackAuthProblem } | 
/**  YouTrack answers 404 also for an issue the user may not see */
{ status: "notFound" } | { status: "error"; message: string };

/**  The page to open in the browser for the app's own sign-in; `wait_youtrack_sign_in` waits for its answer */
export type YouTrackSignIn = {
	authorizeUrl: string,
};

/**  The state field of an issue: the field whose type is a state (`StateIssueCustomField`) */
export type YouTrackState = {
	/**  The name of the field, usually "State" */
	field: string,
	value: string | null,
	/**  The value is a resolved state (Fixed, Duplicate, Obsolete…) */
	resolved: boolean,
	/**  The field has the value `Fixed` (asked only for an issue that is not resolved): Mark Fixed sets it */
	hasFixed: boolean,
};

/**  The state an issue had before a change of it, for its undo */
export type YouTrackStateChange = {
	field: string,
	previous: string | null,
};

/**  Where the YouTrack token came from, in the order they are tried (`youtrack::service`) */
export type YouTrackTokenSource = 
/**  `YOUTRACK_TOKEN` with `YOUTRACK_BASE_URL`, as the `youtrack` CLI reads them */
"environment" | 
/**  The app's own sign-in in the browser (Hub OAuth with a refresh token) */
"signIn" | 
/**  A token the user pasted in Settings */
"pastedToken";

/**  The user a token belongs to */
export type YouTrackUser = {
	login: string,
	fullName: string,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

